  "cpp/runtime-objc/NabObjCBlocks.h":
      "// native-api-bindgen React Native runtime (JSI <-> Objective-C): blocks.\n// Licensed under the Apache License, Version 2.0 (project source).\n// Objective-C++ only (included by the runtime and the generated block\n// factories, never by plain C++ translation units).\n#pragma once\n\n#import <Foundation/Foundation.h>\n\n#include <memory>\n#include <string>\n#include <vector>\n\n#include \"NabObjCRuntime.h\"\n\nnamespace nab::objc {\n\n/// A JavaScript function wrapped as an Objective-C block. Owned by the block\n/// (shared_ptr captured by it); the JS function is released on the JS thread.\nstruct BlockTarget;\n\n/// Creates a block of one native signature that forwards to [target].\nusing BlockMaker = id (*)(std::shared_ptr<BlockTarget> target);\n\n/// One generated block signature: [key] is referenced by `B<key>;`\n/// conversion codes, [codes] are the JS codes of the result and arguments\n/// (`v`, `z`, `n`, `j`, `s`, `o`).\nstruct BlockFactory {\n  const char* key;\n  const char* codes;\n  BlockMaker make;\n};\n\n/// Called by generated blocks with boxed arguments (NSNumber for scalars,\n/// objects as-is, nil allowed). On the JS thread the function runs\n/// synchronously and its boxed result is returned; elsewhere a `void`\n/// block's call is posted to the JS thread (arguments stay retained until\n/// then) and nil is returned. Non-void blocks invoked off the JS thread\n/// cannot wait for JavaScript: they log and return nil / 0.\nid callBlock(const std::shared_ptr<BlockTarget>& target, std::vector<id> args);\n\n} // namespace nab::objc\n",
  "cpp/runtime-objc/NabNativeViewManager.mm":
      "// native-api-bindgen React Native runtime: native UI layer.\n// Licensed under the Apache License, Version 2.0 (project source).\n#import <React/RCTViewManager.h>\n#import <UIKit/UIKit.h>\n\n// Provided by NabObjCRuntime.mm (views registered from JavaScript).\nextern \"C\" UIView* NabViewForId(NSInteger viewId);\n\n/// `<NativeView>`: a container showing a UIView created through generated\n/// bindings. Served to the New Architecture by the legacy interop layer.\n@interface NabNativeViewManager : RCTViewManager\n@end\n\n@implementation NabNativeViewManager\n\nRCT_EXPORT_MODULE(NabNativeView)\n\n- (UIView*)view {\n  return [UIView new];\n}\n\nRCT_CUSTOM_VIEW_PROPERTY(viewId, NSInteger, UIView) {\n  for (UIView* sub in [view.subviews copy]) [sub removeFromSuperview];\n  UIView* hosted = NabViewForId(json == nil ? 0 : [json integerValue]);\n  if (hosted == nil) return;\n  [hosted removeFromSuperview];\n  hosted.frame = view.bounds;\n  hosted.autoresizingMask = UIViewAutoresizingFlexibleWidth | UIViewAutoresizingFlexibleHeight;\n  [view addSubview:hosted];\n}\n\n@end\n",
  "src/native-view.ts":
      "// native-api-bindgen React Native runtime: native UI layer.\n// Apache License, Version 2.0.\nimport React from 'react';\nimport { requireNativeComponent, type ViewProps } from 'react-native';\n\ntype NabNativeViewProps = ViewProps & { viewId: number };\n\nlet component: React.ComponentType<NabNativeViewProps> | undefined;\n\ninterface ViewRegistry {\n  registerView(h: object): number;\n  unregisterView(id: number): void;\n}\n\nfunction registry(): ViewRegistry {\n  const r = (globalThis as unknown as { __nab?: ViewRegistry }).__nab;\n  if (r === undefined) {\n    throw new Error('native-api-bindgen: runtime not installed (create the view through the bindings first)');\n  }\n  return r;\n}\n\n/** Props of {@link NativeView}. */\nexport interface NativeViewProps extends ViewProps {\n  /** An `android.view.View` / `UIView` created through generated bindings. */\n  view: { readonly \$h: object };\n}\n\n/**\n * Shows a native view created through generated bindings (Android `View`,\n * iOS `UIView`) in the React tree. The view must not have another parent.\n */\nexport function NativeView(props: NativeViewProps): React.ReactElement {\n  const { view, ...rest } = props;\n  const id = React.useMemo(() => registry().registerView(view.\$h), [view]);\n  React.useEffect(() => () => registry().unregisterView(id), [id]);\n  component ??= requireNativeComponent<NabNativeViewProps>('NabNativeView');\n  return React.createElement(component, { ...rest, viewId: id });\n}\n",
